public class ZipArchiveInputStream_getNextZipEntry_TriageGen1Test {

    private byte[] createLFH(String name, int method, boolean hasDataDescriptor, int compressedSize, int uncompressedSize, long crc) {
        // LFH Signature
        ByteBuffer bb = ByteBuffer.allocate(1024).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt(0x04034b50); // LFH_SIG

        // Version made by (2 bytes)
        bb.putShort((short) 0x0200); 
        // General Purpose Bit Flag (2 bytes)
        short flags = 0;
        if (hasDataDescriptor) flags |= 0x0008;
        bb.putShort(flags);

        // Compression Method (2 bytes)
        bb.putShort((short) method);

        // Last mod file time/date (4 bytes)
        bb.putInt(0);

        if (!hasDataDescriptor) {
            bb.putInt((int) crc);
            bb.putInt(compressedSize);
            bb.putInt(uncompressedSize);
        } else {
            bb.putInt(0); // placeholder for CRC
            bb.putInt(0); // placeholder for compressed size
            bb.putInt(0); // placeholder for uncompressed size
        }

        // Filename len (2 bytes)
        byte[] nameBytes = name.getBytes();
        bb.putShort((short) nameBytes.length);

        // Extra len (2 bytes)
        bb.putShort((short) 0);

        // Filename
        bb.put(nameBytes);

        byte[] result = new byte[bb.position()];
        System.arraycopy(bb.array(), 0, result, 0, bb.position());
        return result;
    }

    @Test
    public void testGetNextZipEntry_ClosedOrHitCentralDirectory() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[10]);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);
        zis.close();
        Assert.assertNull(zis.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_EOF() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[0]);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);
        Assert.assertNull(zis.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_CentralDirectorySignatureFound() throws IOException {
        // Simulate finding CFH_SIG instead of LFH_SIG
        ByteBuffer bb = ByteBuffer.allocate(12).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt(0x02014b50); // CFH_SIG
        byte[] data = bb.array();

        InputStream is = new ByteArrayInputStream(data);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        // This should trigger hitCentralDirectory = true and return null because sig != LFH_SIG
        Assert.assertNull(zis.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_ValidStoredEntry() throws IOException {
        byte[] lfh = createLFH("test.txt", 0, false, 4, 4, 12345L);
        InputStream is = new ByteArrayInputStream(lfh);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zis.getNextZipEntry();
        Assert.assertNotNull(entry);
        Assert.assertEquals("test.txt", entry.getName());
        Assert.assertEquals(0, entry.getMethod());
    }

    @Test
    public void testGetNextZipEntry_WithDataDescriptor() throws IOException {
        // Manual construction for Data Descriptor logic
        ByteBuffer bb = ByteBuffer.allocate(1024).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt(0x04034b50); // LFH_SIG
        bb.putShort((short) 0x0200); // version
        bb.putShort((short) 0x0008); // GP bit flag: has data descriptor
        bb.putShort((short) 0);      // method: STORE
        bb.putInt(0);                // time
        bb.putInt(0);                // CRC placeholder
        bb.putInt(0);                // compressed size placeholder
        bb.putInt(0);                // uncompressed size placeholder

        String name = "data.txt";
        bb.putShort((short) name.length());
        bb.putShort((short) 0);      // extra len
        bb.put(name.getBytes());

        // Data Descriptor part (must follow LFH)
        bb.putInt(12345);            // CRC
        bb.putInt(4);                // compressed size
        bb.putInt(4);                // uncompressed size

        byte[] data = new byte[bb.position()];
        System.arraycopy(bb.array(), 0, data, 0, bb.position());

        InputStream is = new ByteArrayInputStream(data);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zis.getNextZipEntry();
        Assert.assertNotNull(entry);
        Assert.assertEquals("data.txt", entry.getName());
    }

    @Test
    public void testGetNextZipEntry_MultipleEntries() throws IOException {
        byte[] entry1 = createLFH("1.txt", 0, false, 4, 4, 1L);
        byte[] entry2 = createLFH("2.txt", 0, false, 4, 4, 2L);

        ByteBuffer bb = ByteBuffer.allocate(entry1.length + entry2.length);
        bb.put(entry1);
        bb.put(entry2);

        InputStream is = new ByteArrayInputStream(bb.array());
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        Assert.assertNotNull(zis.getNextZipEntry());
        Assert.assertEquals("1.txt", zis.getNextZipEntry().getName());
        Assert.assertNull(zis.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_InvalidSignature() throws IOException {
        ByteBuffer bb = ByteBuffer.allocate(12).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt(0x12345678); // Wrong signature
        byte[] data = bb.array();

        InputStream is = new ByteArrayInputStream(data);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        Assert.assertNull(zis.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_CompressionMethods() throws IOException {
        // Test Deflated (Imploding)
        byte[] deflated = createLFH("deflated.txt", 8, false, 4, 4, 1L);
        InputStream is = new ByteArrayInputStream(deflated);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zis.getNextZipEntry();
        Assert.assertNotNull(entry);
        Assert.assertEquals(8, entry.getMethod());
    }
}
